{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([session("a", 1, True), session("b", 1, None),
                            session("c", 1, False)]) == 1 / 3
    assert conversion_rate([]) == 0.0
    assert conversion_rate([session("d", 1, None)]) == 0.0


def test_pooled_rate_weights_sessions_not_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 1, False)] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_fields_and_skipped_lines():
    assert parse_session_log(["\n", "  # comment,ignored\n", " a , 2 , 1 ",
                              "b, -1, 0", " c, 3,   "]) == [
        session("a", 2, True), session("b", -1, False), session("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,nope,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", "ok,1,1", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    first = session("b", 1, True)
    replacement = session("b", 3, False)
    events = [first, session("z", 2, True), replacement,
              session("a", 3, None), session("z", 3, False)]
    assert dedupe_sessions(events) == [session("a", 3, None), replacement,
                                       session("z", 3, False)]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_fills_range_and_ignores_outside():
    events = [session("a", 0, True), session("b", 2, True),
              session("c", 2, True), session("d", 3, None),
              session("e", 4, False), session("f", 5, True)]
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_and_pooled_rate():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 4, True), session("c", 4, False)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("a", 1, True)], "empty": [],
              "a": [session("b", 1, True)], "b": [session("c", 1, False)]}
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_has_sorted_keys_and_none_for_empty():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1, 0], 0),
                                              ([1, 2, 0, 3, -1, 1, 1, 1], 3)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
